// 1. API Connection & Basic Functionality Tests
// ──────────────────────────────────────────────────────────────────────────────

describe.runIf(RUN_INTEGRATION)('API Connection Tests', () => {
  it('should connect to Supabase without errors', async () => {
    // If Supabase is unreachable, this test will fail
    const result = await listDrugs({ limit: 1 })
    expect(result).not.toBeNull()
    expect(result).toBeDefined()
  })

  it('should fetch list of drugs', async () => {
    const result = await listDrugs()
    expect(result).not.toBeNull()
    if (result) {
      expect(result.drugs).toBeDefined()
      expect(Array.isArray(result.drugs)).toBe(true)
      expect(result.total_count).toBeGreaterThan(0)
    }
  })

  it('should have correct response shape for drug list', async () => {
    const result = await listDrugs({ limit: 5 })
    expect(result).toMatchObject({
      drugs: expect.any(Array),
      total_count: expect.any(Number),
      limit: expect.any(Number),
      offset: expect.any(Number),
      has_more: expect.any(Boolean),
    })
  })

  it('should handle pagination parameters', async () => {
    const page1 = await listDrugs({ limit: 5, offset: 0 })
    const page2 = await listDrugs({ limit: 5, offset: 5 })

    expect(page1?.drugs).not.toEqual(page2?.drugs)
    expect(page1?.offset).toBe(0)
    expect(page2?.offset).toBe(5)
  })

  it('should return consistent data types', async () => {
    const result = await listDrugs({ limit: 1 })
    if (result && result.drugs.length > 0) {
      const drug = result.drugs[0]
      expect(typeof drug.pcid_code).toBe('string')
      expect(typeof drug.name).toBe('string')
      expect(typeof drug.slug).toBe('string')
      expect(typeof drug.entity_type).toBe('string')
    }
  })
})

// ──────────────────────────────────────────────────────────────────────────────
// 2. Slug Resolution Tests
// ──────────────────────────────────────────────────────────────────────────────

describe.runIf(RUN_INTEGRATION)('Slug Resolution', () => {
  beforeAll(() => {
    clearSlugCache() // Start clean
  })

  afterEach(() => {
    // Optional: clear cache between tests for isolation
    // clearSlugCache()
  })

  it('should resolve metformin slug to PCID', async () => {
    const pcid = await resolveSlugToPcid('metformin')
    expect(pcid).not.toBeNull()
    expect(pcid).toMatch(/^PCID-\d{7}$/)
  })

  it('should resolve multiple slugs correctly', async () => {
    for (const drug of TEST_DRUGS) {
      const pcid = await resolveSlugToPcid(drug.slug)
      expect(pcid).not.toBeNull()
      expect(pcid).toMatch(/^PCID-\d{7}$/)
    }
  })

  it('should return null for unknown slug', async () => {
    const pcid = await resolveSlugToPcid('unknown-nonexistent-drug-xyz')
    expect(pcid).toBeNull()
  })

  it('should use cache for repeated lookups', async () => {
    clearSlugCache()
    const start = performance.now()
    const pcid1 = await resolveSlugToPcid('metformin')
    const duration1 = performance.now() - start

    const start2 = performance.now()
    const pcid2 = await resolveSlugToPcid('metformin')
    const duration2 = performance.now() - start2

    // Second call should be much faster (cache hit)
    expect(pcid1).toBe(pcid2)
    expect(duration2).toBeLessThan(duration1 * 0.5) // At least 50% faster
  })

  it('should cache size increase with lookups', async () => {
    clearSlugCache()
    const stats1 = getCacheStats()
    expect(stats1.size).toBe(0)

    await resolveSlugToPcid('metformin')
    const stats2 = getCacheStats()
    expect(stats2.size).toBe(1)

    await resolveSlugToPcid('sertraline')
    const stats3 = getCacheStats()
    expect(stats3.size).toBe(2)
  })
})

