describe.runIf(RUN_INTEGRATION)('Drug Detail Fetch', () => {
  it('should fetch metformin by slug', async () => {
    const drug = await getDrugBySlug('metformin')
    expect(drug).not.toBeNull()
    expect(drug?.name).toBe('Metformin')
    expect(drug?.slug).toBe('metformin')
  })

  it('should return null for unknown slug', async () => {
    const drug = await getDrugBySlug('unknown-drug-xyz')
    expect(drug).toBeNull()
  })

  it('should include all required fields', async () => {
    const drug = await getDrugBySlug('metformin')
    expect(drug).toMatchObject({
      pcid_code: expect.any(String),
      name: expect.any(String),
      slug: expect.any(String),
      entity_type: expect.any(String),
      status: expect.any(String),
      attributes: expect.any(Object),
      components: expect.any(Array),
      interactions: expect.any(Array),
      eco_risk: expect.any(Object),
      created_at: expect.any(String),
      updated_at: expect.any(String),
    })
  })

  it('should have valid eco_risk structure', async () => {
    const drug = await getDrugBySlug('metformin')
    if (drug) {
      expect(drug.eco_risk).toMatchObject({
        pec_unit: expect.any(String),
        mec_unit: expect.any(String),
      })
      // Optional fields can be null
      if (drug.eco_risk.rq_value !== null) {
        expect(typeof drug.eco_risk.rq_value).toBe('number')
      }
    }
  })

  it('should fetch multiple drugs', async () => {
    for (const testDrug of TEST_DRUGS.slice(0, 3)) {
      const drug = await getDrugBySlug(testDrug.slug)
      expect(drug).not.toBeNull()
      expect(drug?.name).toBe(testDrug.name)
    }
  })
})

