// 4. Combination Product Tests
// ──────────────────────────────────────────────────────────────────────────────

describe.runIf(RUN_INTEGRATION)('Combination Products', () => {
  it('should fetch augmentin (amoxicillin + clavulanate)', async () => {
    const drug = await getDrugBySlug('augmentin')
    expect(drug).not.toBeNull()
    expect(drug?.name).toMatch(/augmentin/i)
    expect(drug?.entity_type).toBe('combination')
  })

  it('should include components for combination products', async () => {
    const drug = await getDrugBySlug('augmentin')
    if (drug) {
      expect(Array.isArray(drug.components)).toBe(true)
      expect(drug.components.length).toBeGreaterThan(0)
      // Each component should have required fields
      drug.components.forEach(comp => {
        expect(comp.component_pcid_id).toBeDefined()
        expect(comp.component_name).toBeDefined()
        expect(comp.component_slug).toBeDefined()
        expect(comp.role).toMatch(/active_ingredient|synergist|other/)
      })
    }
  })

  it('should have navigable component slugs', async () => {
    const drug = await getDrugBySlug('augmentin')
    if (drug && drug.components.length > 0) {
      // Try to fetch first component by slug
      const comp = drug.components[0]
      const compDrug = await getDrugBySlug(comp.component_slug)
      expect(compDrug).not.toBeNull()
      expect(compDrug?.name).toBe(comp.component_name)
    }
  })
})

