// ──────────────────────────────────────────────────────────────────────────────
// 6. Search Functionality Tests
// ──────────────────────────────────────────────────────────────────────────────

describe.runIf(RUN_INTEGRATION)('Search Functionality', () => {
  it('should search for drugs by prefix', async () => {
    const result = await searchDrugs({ q: 'sert' })
    expect(result).not.toBeNull()
    expect(result?.results).toBeDefined()
  })

  it('should find sertraline when searching "sert"', async () => {
    const result = await searchDrugs({ q: 'sert' })
    const found = result?.results.some(r => r.slug === 'sertraline')
    expect(found).toBe(true)
  })

  it('should find multiple results for broader search', async () => {
    const result = await searchDrugs({ q: 'a' })
    expect(result?.results.length).toBeGreaterThan(1)
  })

  it('should handle pagination in search results', async () => {
    const page1 = await searchDrugs({ q: 'a', limit: 5, offset: 0 })
    const page2 = await searchDrugs({ q: 'a', limit: 5, offset: 5 })

    // Different pages should have different results (if enough results exist)
    if (page1?.total_count && page1.total_count > 5) {
      expect(page1?.results).not.toEqual(page2?.results)
    }
  })

  it('should return empty for nonsense search', async () => {
    const result = await searchDrugs({ q: 'xyzabc123nonexistent' })
    expect(result?.results.length).toBe(0)
  })

  it('should be case-insensitive', async () => {
    const lower = await searchDrugs({ q: 'metro' })
    const upper = await searchDrugs({ q: 'METRO' })
    expect(lower?.results).toEqual(upper?.results)
  })
})

